SELECT CASE WHEN amount >= 3500 THEN 'high' WHEN amount >= 1100 THEN 'mid' ELSE 'low' END AS amount_bucket, ROUND((100 * SUM(CASE WHEN txn_type = 'DEBIT' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_debit, COUNT(DISTINCT amount) AS unique_txn_types FROM transactions WHERE merchant IS NOT NULL GROUP BY CASE WHEN amount >= 3500 THEN 'high' WHEN amount >= 1100 THEN 'mid' ELSE 'low' END;
